let s=1;const o=new Map;function i(){return new Date().toISOString()}function r(){if(o.size)return;const e=["Curta","Média","Longa"];for(const n of e){const t={id:String(s++),nome:n,created_at:i()};o.set(t.id,t)}}async function c(){return r(),{}}function u(e){r();const n=Array.from(o.values()),t=(e??"").trim().toLowerCase();return t?n.filter(a=>a.nome.toLowerCase().includes(t)):n}async function l(e){return r(),o.get(e)??null}async function d(e){r();const n={id:String(s++),nome:e.nome.trim(),created_at:i()};return o.set(n.id,n),n}async function m(e,n){r();const t=o.get(e);if(!t)return null;const a={...t,nome:n.nome.trim()};return o.set(e,a),a}export{u as a,d as c,l as g,c as l,m as u};
